WITH  upsert AS (
    UPDATE
        fnd01_fund_code
    SET
        fnd01_fund_cd      = #{p.fundCode}
      , fnd01_start_date   = #{p.startDate}
      , fnd01_end_date     = #{p.endDate}
      , fnd01_close_yn     = #{p.closeYn}
      , fnd01_plan_yn      = #{p.planYn}
      , fnd01_real_fund_id = #{p.realFundId}
      , fnd01_company_id   = #{p.companyId}
      , fnd01_icam_yn      = #{p.icamYn}
    WHERE
       fnd01_fund_code_id = #{p.fundCodeId}
    RETURNING *
)
INSERT INTO fnd01_fund_code
(
    fnd01_fund_code_id
,   fnd01_fund_cd
,   fnd01_start_date
,   fnd01_end_date
,   fnd01_close_yn
,   fnd01_plan_yn
,   fnd01_real_fund_id
,   fnd01_company_id
,   fnd01_icam_yn
)
SELECT
    #{p.fundCodeId}
,   #{p.fundCode}
,   #{p.startDate}
,   #{p.endDate}
,   #{p.closeYn}
,   #{p.planYn}
,   #{p.realFundId}
,   #{p.companyId}
,   #{p.icamYn}
WHERE NOT EXISTS ( SELECT * from upsert )

